// Get binary image data from the HTTP Request node
const binaryFieldName = Object.keys($input.item.binary)[0];
const binaryData = $input.item.binary[binaryFieldName];
const base64Image = binaryData.data;

// Build the OpenRouter API payload with vision
const payload = {
  model: "deepseek/deepseek-v4-flash-vision-exp:batch",
  messages: [
    {
      role: "system",
      content: `You are a QA engineer analyzing a UI screenshot for bugs. Examine the image carefully and return a JSON object with the following fields:
{
  "title": "Short, descriptive bug title (max 80 chars)",
  "description": "Clear description of what the bug is",
  "steps_to_reproduce": ["Step 1", "Step 2", "..."],
  "expected_behavior": "What should happen",
  "actual_behavior": "What actually happens (the bug)",
  "environment": "Browser/OS/Device info if visible",
  "severity": "Critical/Major/Minor/Trivial",
  "visual_clues": ["List of visual anomalies seen in screenshot"]
}
Focus on visual defects: layout breaks, alignment issues, missing elements, color contrast problems, text truncation, overlapping elements, etc.`
    },
    {
      role: "user",
      content: [
        {
          type: "text",
          text: "Analyze this UI screenshot for bugs. Return ONLY valid JSON matching the specified schema."
        },
        {
          type: "image_url",
          image_url: {
            url: `data:image/png;base64,${base64Image}`
          }
        }
      ]
    }
  ],
  response_format: {
    type: "json_object"
  }
};

return [{ json: payload }];

// Parse the OpenRouter API response
const response = $input.item.json;
const llmContent = response.choices[0].message.content;
let bugReport;

try {
  bugReport = JSON.parse(llmContent);
} catch (e) {
  // If JSON parsing fails, try to extract JSON from the text
  const jsonMatch = llmContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    bugReport = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error("Failed to parse LLM response as JSON");
  }
}

// Build steps to reproduce text
const stepsText = (bugReport.steps_to_reproduce || [])
  .map((step, i) => `${i + 1}. ${step}`)
  .join('\n');

// Build visual clues text
const visualCluesText = (bugReport.visual_clues || [])
  .map(clue => `- ${clue}`)
  .join('\n');

// Build the GitHub issue body in Markdown
const body = `## Description\n${bugReport.description || 'No description provided.'}\n\n## Steps to Reproduce\n${stepsText || 'Not specified.'}\n\n## Expected Behavior\n${bugReport.expected_behavior || 'Not specified.'}\n\n## Actual Behavior\n${bugReport.actual_behavior || 'Not specified.'}\n\n## Environment\n${bugReport.environment || 'Not specified.'}\n\n## Severity\n${bugReport.severity || 'Not specified.'}\n\n## Visual Clues\n${visualCluesText || 'None identified.'}\n\n---\n🤖 *Automated bug report generated from screenshot analysis*`;

return [{
  json: {
    title: `[Bug] ${bugReport.title || 'UI Issue Detected'}`,
    body: body,
    labels: ['bug', `severity:${(bugReport.severity || 'unknown').toLowerCase()}`]
  }
}];
